import React, { useState, useEffect } from "react";
import { Link } from "react-router-dom";
import axios from "axios";

/**
 * Dashboard Component
 * This is the main dashboard that the child sees after login.
 * It shows:
 * - Welcome message & buddy
 * - Next appointment
 * - Next medicine
 * - Explore & Learn tiles
 * - Play Zone
 * - Mood tile (interactive)
 */
const Dashboard = () => {
  // ----------------------------
  // State variables
  // ----------------------------

  const [userData, setUserData] = useState(null); // store logged-in user info
  const [buddy, setBuddy] = useState(null); // store user's hospital buddy

  const [nextAppointment, setNextAppointment] = useState(null); // next upcoming appointment
  const [nextMedicine, setNextMedicine] = useState(null); // next medicine to take

  // Array of mood options (6 emojis)
  const [moods, setMoods] = useState([
    { id: 1, emoji: "SmilingFaceWithHalo.png", label: "Happy" },
    { id: 2, emoji: "FaceWithSpiralEyes.png", label: "Confused" },
    { id: 3, emoji: "WinkingFaceWithTongue.png", label: "Silly" },
    { id: 4, emoji: "FaceWithSteamFromNose.png", label: "Angry" },
    { id: 5, emoji: "WoozyFace.png", label: "Proud" },
    { id: 6, emoji: "Sad.png", label: "Sad" },
  ]);

  const [selectedMood, setSelectedMood] = useState(null); // today's selected mood
  const [moodHistory, setMoodHistory] = useState(0); // optional: count days kid has logged mood

  // ----------------------------
  // Load user and buddy from localStorage
  // ----------------------------
  useEffect(() => {
    const storedUser = localStorage.getItem("user");
    const storedBuddy = localStorage.getItem("buddy");

    if (storedUser) setUserData(JSON.parse(storedUser));
    if (storedBuddy) setBuddy(JSON.parse(storedBuddy));
  }, []);

  // ----------------------------
  // Fetch next appointment from backend
  // ----------------------------
  useEffect(() => {
    if (!userData?.id) return; // wait until userData is loaded

    axios
      .get(`http://localhost:5001/api/appointments/${userData.id}/next`)
      .then((res) => setNextAppointment(res.data))
      .catch((err) => console.error("Next appointment error:", err));
  }, [userData]);

  // ----------------------------
  // Fetch next medicine from backend
  // ----------------------------
  useEffect(() => {
    if (!userData?.id) return;

    axios
      .get(`http://localhost:5001/api/medicines/${userData.id}/next`)
      .then((res) => setNextMedicine(res.data))
      .catch((err) => console.error("Next medicine error:", err));
  }, [userData]);

  // ----------------------------
  // Fetch today's mood from backend
  // ----------------------------
  useEffect(() => {
    if (!userData?.id) return;

    axios
      .get(`http://localhost:5001/api/moods/${userData.id}/today`)
      .then((res) => {
        if (res.data) {
          setSelectedMood(res.data); // set today's mood if exists
        }
      })
      .catch((err) => console.error("Error fetching today's mood:", err));
  }, [userData]);

  // ----------------------------
  // Handle marking medicine as taken
  // ----------------------------
  const handleTakeMedicine = (id) => {
    if (!userData?.id) return;

    axios
      .put(`http://localhost:5001/api/medicines/${id}/take`)
      .then(() => {
        // instantly mark medicine as taken for UI feedback
        setNextMedicine((prev) =>
          prev && prev.id === id ? { ...prev, is_taken: 1 } : prev
        );

        // optional: fetch the next medicine after taking current one
        return axios.get(
          `http://localhost:5001/api/medicines/${userData.id}/next`
        );
      })
      .then((res) => setNextMedicine(res.data))
      .catch((err) => console.error("Error updating medicine:", err));
  };

  // ----------------------------
  // Handle selecting a mood
  // ----------------------------
  const handleSelectMood = (moodId) => {
    if (!userData?.id) return;

    // send selected mood to backend
    axios
      .post(`http://localhost:5001/api/moods/${userData.id}`, {
        mood_id: moodId,
      })
      .then((res) => {
        // update local state instantly so user sees selection
        setSelectedMood(res.data);

        // optional: increment streak
        setMoodHistory((prev) => prev + 1);
      })
      .catch((err) => console.error("Error updating mood:", err));
  };

  // ----------------------------
  // Loading state
  // ----------------------------
  if (!userData) return <div className="p-6">Loading...</div>;

  // ----------------------------
  // Main JSX
  // ----------------------------
  return (
    <main className="min-h-screen bg-slate-100 p-4 md:p-8">
      <section className="grid grid-cols-1 lg:grid-cols-[1fr_360px] gap-6">
        {/* --------------------------
            LEFT SIDE: Main Dashboard
        --------------------------- */}
        <div className="grid grid-cols-1 gap-6">
          {/* HEADER */}
          <div className="bg-white rounded-2xl p-6 flex items-center gap-6 shadow">
            {buddy ? (
              <img
                src={`/assets/images/icons/${buddy.icon_filename}`}
                alt={buddy.name}
                className="w-40 h-40 object-contain"
              />
            ) : (
              <div className="w-40 h-40 bg-orange-200 rounded-full" />
            )}

            <div>
              <h2 className="text-4xl font-bold">
                Hi, {userData.firstName} 👋
              </h2>
              {buddy && (
                <p className="text-sm text-gray-500">
                  Your hospital buddy:{" "}
                  <span className="font-medium">{buddy.name}</span>
                </p>
              )}
            </div>
          </div>

          {/* APPOINTMENT & MEDICINE ROW */}
          {/* You can keep your existing JSX for appointments and medicines here */}
        </div>

        {/* --------------------------
            RIGHT SIDE: Mood Tile
        --------------------------- */}
        <div className="order-last lg:order-none bg-purple-500 rounded-2xl p-6 text-white flex flex-col items-center">
          {/* Title */}
          <h3 className="text-2xl font-bold mb-4 text-center">
            Your Mood Today 🌈
          </h3>

          {/* Mood Buttons */}
          <div className="grid grid-cols-2 gap-4 mb-4">
            {moods.map((mood) => (
              <button
                key={mood.id}
                onClick={() => handleSelectMood(mood.id)} // handle click
                className={`p-4 rounded-xl border-4 transition-transform duration-200 ease-in-out ${
                  selectedMood?.mood_id === mood.id
                    ? "border-white scale-125" // highlight selected mood
                    : "border-transparent"
                }`}
                title={mood.label} // tooltip
              >
                <img
                  src={`/assets/images/icons/emoji/${mood.emoji}`}
                  alt={mood.label}
                  className="w-20 h-20 object-contain" // bigger icons
                />
              </button>
            ))}
          </div>

          {/* Encouragement Text */}
          {selectedMood && (
            <div className="text-center">
              <h4 className="font-bold text-lg">
                {selectedMood.encouragement_title}
              </h4>
              <p className="text-sm">{selectedMood.encouragement_text}</p>
            </div>
          )}

          {/* NEW ELEMENT: Mood Streak Counter */}
          <div className="mt-4 text-yellow-300 font-semibold text-center">
            🌟 Mood streak: {moodHistory} day{moodHistory !== 1 ? "s" : ""}
          </div>
        </div>
      </section>
    </main>
  );
};

export default Dashboard;
